css:
/* Фіксуємо Times по всій формі */
.print-format, 
.print-format * {
  font-family: "Times New Roman", Times, serif !important;
  line-height: 1.2;
}
.sheet {
  --cols: 3;
  --label-w: 70mm;
  --label-h: 36mm;
  --gap: 4mm;
  --page-margin: 8mm;
  --qr: 18mm;
  --font: 11px;

  padding: var(--page-margin);
  display: grid;
  grid-template-columns: repeat(var(--cols), var(--label-w));
  grid-auto-rows: var(--label-h);
  gap: var(--gap);
  justify-content: start;
  align-content: start;
  font-family: "Times New Roman", Times, serif; /* або твій sans */
  color: #0f172a;
  font-size: var(--font);
  line-height: 1.2;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.lbl {
  box-sizing: border-box;
  border: 0.3mm solid #e2e8f0;
  border-radius: 2mm;
  padding: 2.5mm 3mm;
  background: #fff;
  display: grid;
  grid-template-rows: auto 1fr;
  overflow: hidden;

  break-inside: avoid;
  page-break-inside: avoid;
}

.lbl-empty { border-color: transparent; visibility: hidden; }

.lbl-top {
  display: grid;
  grid-template-columns: 1fr var(--qr);
  gap: 2mm;
  align-items: start;
}
.lbl-title {
  font-weight: 700;
  font-size: calc(var(--font) + 1px);
  line-height: 1.15;
  max-height: calc(var(--qr) + 4mm);
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  word-break: break-word;
}
.lbl-qr {
  width: var(--qr); 
  height: var(--qr);
  border: 0.3mm solid #e2e8f0;
  border-radius: 1mm;
  padding: 1mm;
  background: #fff;
}
.lbl-qr { display: {{ (qr_mm|int > 0) and 'block' or 'none' }}; }

.lbl-body { margin-top: 1.5mm; display: grid; gap: 1.2mm; }
.lbl-row { display: grid; grid-template-columns: auto 1fr; gap: 1mm; align-items: baseline; }
.lbl-key { font-weight: 700; color: #334155; white-space: nowrap; }
.lbl-val { color: #0f172a; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lbl-id .lbl-val { font-family: "Liberation Mono", "DejaVu Sans Mono", Consolas, monospace; }

html:
{# ------- параметри ------- #}
{%- set cols = (doc.columns or 3) | int -%}
{%- set label_w = (doc.label_width_mm or 70) -%}
{%- set label_h = (doc.label_height_mm or 36) -%}
{%- set gap = (doc.gap_mm if doc.gap_mm is not none else doc["відступ_між_ярликами_мм"]) or 4 -%}
{%- set margin = (doc.page_margin_mm or 8) -%}
{%- set font_px = (doc.font_px or 11) -%}
{%- set qr_mm = (doc.qr_size_mm or 0) -%}
{%- set show_inv = (doc.show_inventory_no or 0) == 1 -%}
{%- set show_sn  = (doc.show_serial_no  or 0) == 1 -%}

{# ------- макрос для одного ярлика ------- #}
{%- macro label_block(item) -%}
  {% set a = frappe.get_cached_doc("oiAsset", item.asset) %}
  {% set title = item.override_title or a.asset_name or a.name %}
  {% set inv   = item.override_inventory_no or a.inventory_no %}
  {% set sn    = item.override_serial_no  or a.serial_no %}
  {% set url   = frappe.utils.get_url_to_form("oiAsset", a.name) %}

  <div class="lbl">
    <div class="lbl-top">
      <div class="lbl-title" title="{{ title }}">{{ title }}</div>
      {% if qr_mm|int > 0 %}
        {% set data_uri = frappe.call("orange_inventory.print_utils.qr.png_data_uri", value=url, box_size=5, border=0) %}
        {% if data_uri %}<img src="{{ data_uri }}" alt="QR" class="lbl-qr"/>{% endif %}
      {% endif %}
    </div>

    <div class="lbl-body">
      {% if show_inv %}
      <div class="lbl-row"><span class="lbl-key">Інв. №:</span><span class="lbl-val">{{ inv or "—" }}</span></div>
      {% endif %}
      {% if show_sn %}
      <div class="lbl-row"><span class="lbl-key">Сер. №:</span><span class="lbl-val">{{ sn or "—" }}</span></div>
      {% endif %}
    </div>
  </div>
{%- endmacro -%}

{# ------- аркуш з етикетками ------- #}
<div class="sheet"
     style="
      --cols: {{ cols }};
      --label-w: {{ label_w }}mm;
      --label-h: {{ label_h }}mm;
      --gap: {{ gap }}mm;
      --page-margin: {{ margin }}mm;
      --qr: {{ qr_mm }}mm;
      --font: {{ font_px }}px;
     ">

  {%- set total = 0 -%}
  {%- for it in doc.items or [] -%}
    {%- set copies = (it.copies or 1) | int -%}
    {%- set total = total + copies -%}
    {%- for i in range(copies) -%}
      {{ label_block(it) }}
    {%- endfor -%}
  {%- endfor -%}

  {# якщо треба добити ряд до кратності колонок #}
  {%- if total and (total % cols) != 0 -%}
    {%- for i in range(cols - (total % cols)) -%}
      <div class="lbl lbl-empty"></div>
    {%- endfor -%}
  {%- endif -%}
</div>
